#include <stdarg.h>
#include <stdio.h>

void my_printf(const char *format, ...);
int main() {
    my_printf("Hello, %s!\n", "World");
    return 0;
}

void my_printf(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}
